from django.db import models
from ..models import TimeStampedModel,WorkflowDefinition
class WorkflowGenome(TimeStampedModel):workflow=models.OneToOneField(WorkflowDefinition,related_name='genome',on_delete=models.CASCADE);complexity=models.DecimalField(max_digits=6,decimal_places=2);risk=models.DecimalField(max_digits=6,decimal_places=2);cost=models.DecimalField(max_digits=6,decimal_places=2);automation=models.DecimalField(max_digits=6,decimal_places=2);governance=models.DecimalField(max_digits=6,decimal_places=2);ai_readiness=models.DecimalField(max_digits=6,decimal_places=2);features=models.JSONField(default=dict);version=models.CharField(max_length=40,default='1')
class WorkflowBenchmark(TimeStampedModel):workflow=models.ForeignKey(WorkflowDefinition,related_name='benchmarks',on_delete=models.CASCADE);cohort=models.CharField(max_length=120);metrics=models.JSONField(default=dict);percentiles=models.JSONField(default=dict);source=models.CharField(max_length=100,default='internal')
